insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values
('78300000-0000-4000-8000-000009000971','40000000-0000-4000-8000-000000900097','Identifique os vetores','Considere $u=(1,1)$ e $v=(1,-1)$, ambos não nulos.',1),
('78300000-0000-4000-8000-000009000972','40000000-0000-4000-8000-000000900097','Calcule o produto interno','$\langle u,v\rangle=1\cdot1+1\cdot(-1)=0$.',2),
('78300000-0000-4000-8000-000009000973','40000000-0000-4000-8000-000000900097','Use a condição geométrica','Produto interno zero entre vetores não nulos significa que eles são ortogonais.',3),
('78300000-0000-4000-8000-000009000974','40000000-0000-4000-8000-000000900097','Confira pela fórmula do ângulo','$\cos\theta=\dfrac{\langle u,v\rangle}{\|u\|\,\|v\|}=0$.',4),
('78300000-0000-4000-8000-000009000975','40000000-0000-4000-8000-000000900097','Relacione à alternativa','Logo $\theta=90^\circ$, correspondente à alternativa C.',5);
