-- Álgebra Linear, bloco 03: substitui orientações repetidas por conteúdo específico.
begin;

delete from public.question_hints
where question_id >= '40000000-0000-4000-8000-000000900073'
  and question_id <= '40000000-0000-4000-8000-000000900108';

delete from public.question_solution_steps
where question_id = '40000000-0000-4000-8000-000000900097';



update public.question_options
set content_markdown = case label
  when 'A' then '$0^\circ$' when 'B' then '$180^\circ$'
  when 'C' then '$90^\circ$' when 'D' then '$45^\circ$' end
where question_id = '40000000-0000-4000-8000-000000900097';

update public.question_solutions
set final_answer_markdown = '$90^\circ$',
    explanation_markdown = 'O produto interno dos vetores é zero e ambos são não nulos. Essa condição caracteriza um ângulo reto no espaço euclidiano. Portanto, $\theta=90^\circ$.'
where question_id = '40000000-0000-4000-8000-000000900097';

commit;
